/* ---- Clue add / list / clear ---- */
function num(id){const v=parseFloat(document.getElementById(id).value);return Number.isFinite(v)?v:null;}
function flash(msg){document.getElementById("area-status").innerHTML=`<b style="color:#ffb020">${msg}</b>`;}
function buildRadarClue(lat,lng,km,unit,hit){
  if(lat==null||lng==null||km==null||!(km>0)) return {error:"Radar needs a centre point and a positive radius."};
  const disp=Math.round(fromKm(km,unit)*100)/100;
  return {clue:{kind:"radar",
    label:`<span class="idx">R</span> Radar · ${hit?"hit, inside":"miss, outside"} · ${disp} ${unit}<br><span class="hint">@ ${lat.toFixed(3)}, ${lng.toFixed(3)}</span>`,
    poly:circle(lat,lng,km), mode:hit?"i":"d", share:{t:"R",lat,lng,km,hit,unit}}};
}
function buildThermoClue(aLat,aLng,bLat,bLng,hotter,questionKm,unit){
  if([aLat,aLng,bLat,bLng].some(v=>v==null)) return {error:"Thermometer needs both a start and an end point."};
  unit=unit||UNITS;
  const distKm=turf.distance(turf.point([aLng,aLat]),turf.point([bLng,bLat]),{units:"kilometers"});
  const short=questionKm!=null&&distKm<questionKm;
  const shortTxt=short?` <b style="color:#ffb020">(short of the ${fmtDist(questionKm,unit)} question)</b>`:"";
  return {clue:{kind:"thermo",
    label:`<span class="idx">T</span> Thermometer · ${hotter?"hotter":"colder"} · ${fmtDist(distKm,unit)} travelled${shortTxt}<br><span class="hint">${aLat.toFixed(3)},${aLng.toFixed(3)} → ${bLat.toFixed(3)},${bLng.toFixed(3)}</span>`,
    poly:halfPlane([aLng,aLat],[bLng,bLat],hotter), mode:"i", share:{t:"T",aLat,aLng,bLat,bLng,hotter,questionKm,unit}}};
}
function matchClue(mode,lat,lng,same,labelHtml,poly){
  return {clue:{kind:"match",label:labelHtml,poly,mode:same?"i":"d",share:{t:"M",mode,lat,lng,same}}};
}
function buildMatchClue(mode,lat,lng,same){
  if(lat==null||lng==null) return {error:"Matching needs your location."};
  if(mode==="municipality"){
    const f=municipalityAt(lat,lng);
    if(!f) return {error:"That point does not resolve to a municipality."};
    return matchClue(mode,lat,lng,same,
      `<span class="idx">M</span> Matching · ${same?"same":"different"} municipality<br><span class="hint">${f.n} (${f.k}) · not Google-verified</span>`,
      turf.feature(f.g));
  }
  if(mode==="canton"){
    const f=cantonAt(lat,lng);
    if(!f) return {error:"That point does not resolve to a canton."};
    return matchClue(mode,lat,lng,same,
      `<span class="idx">M</span> Matching · ${same?"same":"different"} canton · ${f.properties.code}<br><span class="hint">${f.properties.name}</span>`,
      turf.feature(f.geometry));
  }
  if(mode==="district"){
    if(!DISTRICTS.length) return {error:"District data is not loaded. Run scripts/fetch_districts.py first."};
    const f=districtAt(lat,lng);
    if(!f) return {error:"That point is not inside any district. Some cantons have abolished districts, which is a valid null answer under the rulebook - no area can be cut from this question."};
    return matchClue(mode,lat,lng,same,
      `<span class="idx">M</span> Matching · ${same?"same":"different"} district · not Google-verified<br><span class="hint">${f.name}</span>`,
      f.feature);
  }
  if(mode==="transitline"){
    if(!TRANSIT_LINES.length) return {error:"Transit line data is not loaded. Run scripts/fetch_transit_lines.py first."};
    const pts=setFor("station");
    if(pts.length<1) return {error:"No stations loaded."};
    const near=nearestOf(pts,lat,lng);
    const lines=TRANSIT_BY_STATION.get(near.place.name);
    if(!lines||!lines.length) return {error:`No rail line in our data stops at ${near.place.name} (your nearest station). This may be a real gap in the transit data (heritage/rack railways are not covered) rather than a true null answer - see data/transit-lines-report.txt.`};
    const reachable=new Set();
    for(const line of lines) for(const s of line.stops) reachable.add(s);
    const reachedPts=pts.filter(p=>reachable.has(p.name));
    const poly=multiBufferKm(reachedPts,HIDE_RADIUS_KM);
    if(!poly) return {error:"Could not build that area."};
    return matchClue(mode,lat,lng,same,
      `<span class="idx">M</span> Matching · ${same?"yes":"no"} transit line · not Google-verified<br><span class="hint">${near.place.name} · ${lines.length} line${lines.length===1?"":"s"}, ${reachedPts.length} stations reachable</span>`,
      poly);
  }
  if(mode==="stationlen"){
    const pts=setFor("station");
    if(pts.length<2) return {error:"Not enough station data loaded for that question."};
    const near=nearestOf(pts,lat,lng);
    const len=near.place.name.length;
    const group=pts.filter(p=>p.name.length===len);
    const cells=group.map(p=>voronoiCellFor("station",p)).filter(Boolean);
    const poly=dissolveUnion(cells);
    if(!poly) return {error:"Could not compute that area."};
    return matchClue(mode,lat,lng,same,
      `<span class="idx">M</span> Matching · ${same?"same":"different"} station name length · ${len} characters<br><span class="hint">${near.place.name} · ${group.length} station${group.length===1?"":"s"} share that length</span>`,
      poly);
  }
  const pts=setFor(mode);
  if(pts.length<2) return {error:"Not enough "+(REF_LABEL[mode]||mode)+" data loaded for that question."};
  const near=nearestOf(pts,lat,lng);
  const cell=voronoiCellFor(mode,near.place);
  if(!cell) return {error:"Could not compute that area."};
  return matchClue(mode,lat,lng,same,
    `<span class="idx">M</span> Matching · ${same?"same":"different"} nearest ${REF_LABEL[mode]}<br><span class="hint">${near.place.name}</span>`,
    cell);
}
function buildMeasureClue(ref,lat,lng,closer,unit){
  unit=unit||UNITS;
  return new Promise(resolve=>{
    if(lat==null||lng==null){resolve({error:"Measuring needs your location."});return;}
    if(ref==="cantonborder"||ref==="water"||ref==="districtborder"||ref==="highspeed"){
      const multi=ref==="water"?waterLines():ref==="districtborder"?districtLines():ref==="highspeed"?highspeedLines():cantonLines();
      if(!multi){
        const script=ref==="districtborder"?"fetch_districts.py":ref==="highspeed"?null:"fetch_osm_layers.py";
        resolve({error:script?`That layer is not loaded. Run scripts/${script} first.`:"That layer is not loaded. data/highspeed-lines.json is missing."});return;
      }
      const km=multiLineDistKm(lat,lng,multi);
      if(km===null){resolve({error:"Could not measure to that layer."});return;}
      setTimeout(()=>{
        try{
          const band=ref==="water"?bandAroundPolys(waterFeatures(),km):ref==="districtborder"?districtBorderBand(km):ref==="highspeed"?highspeedBand(km):cantonBorderBand(km);
          const unverified=ref==="water"||ref==="districtborder"||ref==="highspeed";
          resolve({clue:{kind:"measure",
            label:`<span class="idx">Ms</span> Measuring · hider ${closer?"closer":"further"} · ${REF_LABEL[ref]}<br><span class="hint">you: ${fmtDist(km,unit)}${unverified?" · not Google-verified":""}</span>`,
            poly:band, mode:closer?"i":"d", share:{t:"S",ref,lat,lng,closer,unit}}});
        }catch(err){resolve({error:"Could not build that measuring clue. "+err.message});}
      },0);
      return;
    }
    if(ref==="elevation"){
      if(!ELEVATION_GRID){resolve({error:"Elevation data is not loaded. Run scripts/fetch_elevation.py first."});return;}
      const near=nearestElevation(lat,lng);
      if(!near){resolve({error:"Could not find elevation data near that point."});return;}
      setTimeout(()=>{
        try{
          const band=elevationBand(near.elev);
          if(!band){resolve({error:"Could not build that area."});return;}
          resolve({clue:{kind:"measure",
            label:`<span class="idx">Ms</span> Measuring · hider ${closer?"higher":"lower"} · elevation · not Google-verified<br><span class="hint">you: ${near.elev} m (nearest ${ELEVATION_GRID.spacingKm} km grid point)</span>`,
            poly:band, mode:closer?"i":"d", share:{t:"S",ref,lat,lng,closer,unit}}});
        }catch(err){resolve({error:"Could not build that measuring clue. "+err.message});}
      },0);
      return;
    }
    if(ref==="border"){
      const km=borderDistanceKm(lat,lng);
      setTimeout(()=>{
        try{
          resolve({clue:{kind:"measure",
            label:`<span class="idx">Ms</span> Measuring · hider ${closer?"closer":"further"} · ${REF_LABEL.border}<br><span class="hint">you: ${fmtDist(km,unit)}</span>`,
            poly:borderBandKm(km), mode:closer?"i":"d", share:{t:"S",ref,lat,lng,closer,unit}}});
        }catch(err){resolve({error:"Could not build that measuring clue. "+err.message});}
      },0);
      return;
    }
    const pts=setFor(ref);
    if(!pts.length){resolve({error:"No places loaded for that category yet."});return;}
    const near=nearestOf(pts,lat,lng);
    setTimeout(()=>{
      try{
        resolve({clue:{kind:"measure",
          label:`<span class="idx">Ms</span> Measuring · hider ${closer?"closer":"further"} · nearest ${REF_LABEL[ref]}<br><span class="hint">you: ${fmtDist(near.km,unit)} (${near.place.name})</span>`,
          poly:multiBufferKm(pts,near.km), mode:closer?"i":"d", share:{t:"S",ref,lat,lng,closer,unit}}});
      }catch(err){resolve({error:"Could not build that measuring clue. "+err.message});}
    },0);
  });
}
function buildTentacleClue(ref,lat,lng,km,unit,pLat,pLng){
  if(lat==null||lng==null) return {error:"Tentacles need your own location. The rulebook measures the radius from the asker."};
  if(km==null||!(km>0)) return {error:"Enter the tentacle radius."};
  const disp=Math.round(fromKm(km,unit)*100)/100;
  const disk=circle(lat,lng,km);
  if(pLat==null||pLng==null){
    return {clue:{kind:"tentacle",
      label:`<span class="idx">Tn</span> Tentacles · not in range · ${REF_LABEL[ref]} · ${disp} ${unit}<br><span class="hint">@ ${lat.toFixed(3)}, ${lng.toFixed(3)}</span>`,
      poly:disk, mode:"d", share:{t:"N",ref,lat,lng,km,unit,pLat:null,pLng:null}}};
  }
  const cands=withinOf(setFor(ref),lat,lng,km);
  if(!cands.length) return {error:"No "+(REF_LABEL[ref]||ref)+" within range, so this clue has no candidates."};
  const place=nearestOf(cands,pLat,pLng).place;
  let poly=disk;
  if(cands.length>=2){
    const cell=voronoiCellForSet(cands,place);
    if(cell){const x=turf.intersect(cell,disk); if(x) poly=x;}
  }
  return {clue:{kind:"tentacle",
    label:`<span class="idx">Tn</span> Tentacles · ${REF_LABEL[ref]} · ${disp} ${unit} · ${cands.length} in range<br><span class="hint">${place.name}</span>`,
    poly, mode:"i", share:{t:"N",ref,lat,lng,km,unit,pLat:place.lat,pLng:place.lng}}};
}
function buildStationClue(lat,lng){
  if(lat==null||lng==null) return {error:"Pick a station from the list."};
  const pts=setFor("station");
  if(!pts.length) return {error:"No stations loaded."};
  const station=nearestOf(pts,lat,lng).place;
  return {clue:{kind:"station",
    label:`<span class="idx">!</span> Station identified · ${station.name}<br><span class="hint">@ ${station.lat.toFixed(3)}, ${station.lng.toFixed(3)}</span>`,
    poly:circle(station.lat,station.lng,HIDE_RADIUS_KM), mode:"i", share:{t:"P",lat:station.lat,lng:station.lng}}};
}
let stationHighlight=null;
function highlightStation(lat,lng){
  if(stationHighlight) map.removeLayer(stationHighlight);
  stationHighlight=L.circleMarker([lat,lng],{radius:11,color:"#fff",weight:3,fillColor:"#e30613",fillOpacity:1}).addTo(map);
  map.flyTo([lat,lng],Math.max(map.getZoom(),14));
}
function addClue(clue){
  if(!clue||!clue.poly){flash("Could not build that clue. Check the inputs.");return false;}
  if(editingIndex!=null){
    clues[editingIndex]=clue;
    exitEditUI();
  } else {
    clues.push(clue);
  }
  renderClues();
  return true;
}
function exitEditUI(){
  editingIndex=null;
  const cb=document.getElementById("cancel-edit"); if(cb) cb.hidden=true;
  document.querySelectorAll(".add").forEach(b=>b.textContent="Add clue");
}
function saveClues(){try{localStorage.setItem("clues",JSON.stringify(clues));}catch(e){}}
function renderClues(){
  saveClues();
  const list=document.getElementById("clue-list");
  document.getElementById("clear-clues").hidden=!clues.length;
  if(!clues.length){ list.innerHTML='<p class="hint" id="clue-empty">No clues yet. Add one above and the map narrows down.</p>'; drawDeduction(); return; }
  list.innerHTML="";
  clues.forEach((c,i)=>{const d=document.createElement("div");d.className="clue"+(i===editingIndex?" editing":"");
    d.innerHTML=`<div>${c.label}</div><div class="clue-actions"><button class="edit" data-i="${i}" title="Edit">✏️</button><button class="x" data-i="${i}" title="Remove">×</button></div>`;
    list.appendChild(d);});
  list.querySelectorAll(".edit").forEach(x=>x.addEventListener("click",()=>{startEdit(+x.dataset.i);}));
  list.querySelectorAll(".x").forEach(x=>x.addEventListener("click",()=>{
    const idx=+x.dataset.i;
    clues.splice(idx,1);
    if(editingIndex===idx){ exitEditUI(); }
    else if(editingIndex!=null&&idx<editingIndex){ editingIndex--; }
    renderClues();
  }));
  drawDeduction();
}
// Repopulates the form for the clue's own kind from clue.share, which holds
// exactly the inputs a builder needs, then hands off to the normal add-*
// handler via editingIndex so committing runs through the same builder.
function startEdit(i){
  const c=clues[i]; if(!c||!c.share) return;
  const s=c.share;
  clearDraft();
  switch(s.t){
    case "R":
      setTool("radar");
      document.getElementById("rad-lat").value=s.lat.toFixed(5);
      document.getElementById("rad-lng").value=s.lng.toFixed(5);
      showDraft("radar",s.lat,s.lng);
      UNITS=s.unit; refreshUnitUI();
      document.getElementById("rad-mi").value=Math.round(fromKm(s.km,s.unit)*100)/100;
      setAns("radar",s.hit?"hit":"miss");
      break;
    case "T":
      setTool("thermo");
      document.getElementById("th-alat").value=s.aLat.toFixed(5);
      document.getElementById("th-alng").value=s.aLng.toFixed(5);
      document.getElementById("th-blat").value=s.bLat.toFixed(5);
      document.getElementById("th-blng").value=s.bLng.toFixed(5);
      showDraft("thermoA",s.aLat,s.aLng); showDraft("thermoB",s.bLat,s.bLng);
      UNITS=s.unit||UNITS; THERMO_QUESTION_KM=s.questionKm!=null?s.questionKm:THERMO_QUESTION_KM; refreshUnitUI();
      setAns("thermo",s.hotter?"hotter":"colder");
      break;
    case "M":
      setTool("match");
      document.getElementById("mt-lat").value=s.lat.toFixed(5);
      document.getElementById("mt-lng").value=s.lng.toFixed(5);
      showDraft("match",s.lat,s.lng);
      document.getElementById("mt-ref").value=s.mode;
      updateMatchAnsLabels();
      setAns("match",s.same?"same":"different");
      break;
    case "S":
      setTool("measure");
      document.getElementById("ms-lat").value=s.lat.toFixed(5);
      document.getElementById("ms-lng").value=s.lng.toFixed(5);
      showDraft("measure",s.lat,s.lng);
      document.getElementById("ms-ref").value=s.ref;
      updateMeasureAnsLabels();
      setAns("measure",s.closer?"closer":"further");
      break;
    case "N": {
      setTool("tentacle");
      document.getElementById("tn-ref").value=s.ref;
      document.getElementById("tn-lat").value=s.lat.toFixed(5);
      document.getElementById("tn-lng").value=s.lng.toFixed(5);
      showDraft("tentacle",s.lat,s.lng);
      UNITS=s.unit; refreshUnitUI();
      document.getElementById("tn-mi").value=Math.round(fromKm(s.km,s.unit)*100)/100;
      setAns("tent",s.pLat!=null?"named":"none");
      if(s.pLat!=null){
        const place=nearestOf(setFor(s.ref),s.pLat,s.pLng).place;
        document.getElementById("tn-name").value=place?place.name:"";
      } else {
        document.getElementById("tn-name").value="";
      }
      break;
    }
    case "P": {
      setTool("station");
      const place=nearestOf(setFor("station"),s.lat,s.lng).place;
      document.getElementById("st-name").value=place?place.name:"";
      break;
    }
    default: return;
  }
  editingIndex=i;
  document.querySelectorAll(".add").forEach(b=>b.textContent="Update clue");
  const cb=document.getElementById("cancel-edit"); if(cb) cb.hidden=false;
  renderClues();
  document.body.classList.remove("nav-open");
}
function rebuildTnList(){
  const sel=document.getElementById("tn-ref"); if(!sel) return;
  const dl=document.getElementById("tn-list"); if(!dl) return;
  let pts=setFor(sel.value);
  const lat=num("tn-lat"), lng=num("tn-lng"), dist=num("tn-mi");
  if(lat!==null&&lng!==null&&dist!==null&&dist>0) pts=withinOf(pts,lat,lng,toKm(dist,UNITS));
  pts=pts.slice().sort((a,b)=>a.name.localeCompare(b.name)).slice(0,400);
  dl.innerHTML=pts.map(p=>`<option value="${String(p.name).replace(/"/g,"&quot;")}"></option>`).join("");
}
function rebuildStList(){
  const dl=document.getElementById("st-list"); if(!dl) return;
  const pts=setFor("station").slice().sort((a,b)=>a.name.localeCompare(b.name)).slice(0,400);
  dl.innerHTML=pts.map(p=>`<option value="${String(p.name).replace(/"/g,"&quot;")}"></option>`).join("");
}
function updateThermoDistance(){
  const el=document.getElementById("th-dist");
  if(!el) return;
  const aLat=num("th-alat"),aLng=num("th-alng"),bLat=num("th-blat"),bLng=num("th-blng");
  if(aLat==null||aLng==null||bLat==null||bLng==null){el.innerHTML="";return;}
  const distKm=turf.distance(turf.point([aLng,aLat]),turf.point([bLng,bLat]),{units:"kilometers"});
  const short=distKm<THERMO_QUESTION_KM;
  const distTxt=fmtDist(distKm,UNITS), questionTxt=fmtDist(THERMO_QUESTION_KM,UNITS);
  el.innerHTML=short
    ? `<b style="color:#ffb020">${distTxt} travelled, short of the ${questionTxt} question</b>`
    : `${distTxt} travelled · ${questionTxt} question`;
}

document.getElementById("add-radar").addEventListener("click",()=>{
  const lat=num("rad-lat"),lng=num("rad-lng"),dist=num("rad-mi");
  if(lat===null||lng===null){flash("Set a centre point first (Pick or type lat, lng).");return;}
  if(dist===null||dist<=0){flash("Enter a radius.");return;}
  const hit=ans.radar==="hit";
  const r=buildRadarClue(lat,lng,toKm(dist,UNITS),UNITS,hit);
  if(r.error){flash(r.error);return;}
  addClue(r.clue);
  clearDraft(["radar"]); document.getElementById("rad-lat").value="";document.getElementById("rad-lng").value="";
});
document.getElementById("th-presets").addEventListener("click",e=>{
  const b=e.target.closest("button"); if(!b) return;
  THERMO_QUESTION_KM=parseFloat(b.dataset.km);
  document.querySelectorAll("#th-presets button").forEach(x=>setOn(x,x===b));
  updateThermoDistance();
});
["th-alat","th-alng","th-blat","th-blng"].forEach(id=>document.getElementById(id).addEventListener("input",updateThermoDistance));
document.getElementById("add-thermo").addEventListener("click",()=>{
  const alat=num("th-alat"),alng=num("th-alng"),blat=num("th-blat"),blng=num("th-blng");
  if([alat,alng,blat,blng].some(v=>v===null)){flash("Set both the start and end points.");return;}
  const hotter=ans.thermo==="hotter";
  const r=buildThermoClue(alat,alng,blat,blng,hotter,THERMO_QUESTION_KM,UNITS);
  if(r.error){flash(r.error);return;}
  addClue(r.clue);
  clearDraft(["thermoA","thermoB"]);
  ["th-alat","th-alng","th-blat","th-blng"].forEach(id=>document.getElementById(id).value="");
  updateThermoDistance();
});
function updateMatchAnsLabels(){
  const isLine=document.getElementById("mt-ref").value==="transitline";
  const box=document.querySelector('.ans[data-ans="match"]');
  if(!box) return;
  box.querySelector('[data-v="same"]').textContent=isLine?"Yes":"Same as me";
  box.querySelector('[data-v="different"]').textContent=isLine?"No":"Different";
}
document.getElementById("mt-ref").addEventListener("change",updateMatchAnsLabels);
updateMatchAnsLabels();
document.getElementById("add-match").addEventListener("click",()=>{
  const lat=num("mt-lat"),lng=num("mt-lng");
  if(lat===null||lng===null){flash("Set your point first (Pick or type lat, lng).");return;}
  const same=ans.match==="same";
  const mode=document.getElementById("mt-ref").value;
  const r=buildMatchClue(mode,lat,lng,same);
  if(r.error){flash(r.error);return;}
  addClue(r.clue);
  clearDraft(["match"]); document.getElementById("mt-lat").value="";document.getElementById("mt-lng").value="";
});
function updateMeasureAnsLabels(){
  const isElev=document.getElementById("ms-ref").value==="elevation";
  const box=document.querySelector('.ans[data-ans="measure"]');
  if(!box) return;
  box.querySelector('[data-v="closer"]').textContent=isElev?"Higher":"Hider closer";
  box.querySelector('[data-v="further"]').textContent=isElev?"Lower":"Hider further";
}
document.getElementById("ms-ref").addEventListener("change",updateMeasureAnsLabels);
updateMeasureAnsLabels();
document.getElementById("add-measure").addEventListener("click",()=>{
  const lat=num("ms-lat"),lng=num("ms-lng"); const ref=document.getElementById("ms-ref").value;
  if(lat===null||lng===null){flash("Set your point first (Pick or type lat, lng).");return;}
  const closer=ans.measure==="closer";
  flash(ref==="border"?"Computing border area…":ref==="elevation"?"Computing elevation contour… this can take a few seconds.":(ref==="cantonborder"||ref==="water"||ref==="districtborder"||ref==="highspeed")?"Computing area… this one takes a second or two.":"Computing distance area… stations can take a few seconds.");
  buildMeasureClue(ref,lat,lng,closer,UNITS).then(r=>{
    if(r.error){flash(r.error);return;}
    addClue(r.clue);
    clearDraft(["measure"]); document.getElementById("ms-lat").value="";document.getElementById("ms-lng").value="";
  });
});
document.getElementById("tn-ref").addEventListener("change",e=>{document.getElementById("tn-mi").value=tentDefaultDisplay(e.target.value);rebuildTnList();});
document.getElementById("tn-name").addEventListener("focus",rebuildTnList);
document.getElementById("add-tentacle").addEventListener("click",()=>{
  const ref=document.getElementById("tn-ref").value;
  const R=num("tn-mi"), lat=num("tn-lat"), lng=num("tn-lng");
  if(lat===null||lng===null){flash("Set your own location first. The rulebook measures the tentacle radius from the asker.");return;}
  if(R===null||R<=0){flash("Enter the tentacle radius.");return;}
  const Rkm=toKm(R,UNITS);
  if(ans.tent==="none"){
    const r=buildTentacleClue(ref,lat,lng,Rkm,UNITS,null,null);
    if(r.error){flash(r.error);return;}
    addClue(r.clue);
    clearDraft(["tentacle"]); return;
  }
  const cands=withinOf(setFor(ref),lat,lng,Rkm);
  if(!cands.length){flash("No "+REF_LABEL[ref]+" within "+R+" "+UNITS+" of you, so this is a null answer under the rules. No area can be cut.");return;}
  const q=(document.getElementById("tn-name").value||"").trim().toLowerCase();
  if(!q){flash("Type the place the hider named.");return;}
  const place=cands.find(p=>p.name.toLowerCase()===q)||cands.find(p=>p.name.toLowerCase().includes(q));
  if(!place){flash("No "+REF_LABEL[ref]+" within range matches that name. Only places inside your radius count.");return;}
  const r=buildTentacleClue(ref,lat,lng,Rkm,UNITS,place.lat,place.lng);
  if(r.error){flash(r.error);return;}
  addClue(r.clue);
  clearDraft(["tentacle"]); document.getElementById("tn-name").value="";
});
document.getElementById("rad-presets").addEventListener("click",e=>{
  const b=e.target.closest("button"); if(!b) return;
  document.getElementById("rad-mi").value=b.dataset.v;
});
document.getElementById("st-name").addEventListener("focus",rebuildStList);
document.getElementById("add-station").addEventListener("click",()=>{
  const q=(document.getElementById("st-name").value||"").trim().toLowerCase();
  if(!q){flash("Type or pick the station name.");return;}
  const pts=setFor("station");
  const station=pts.find(p=>p.name.toLowerCase()===q)||pts.find(p=>p.name.toLowerCase().includes(q));
  if(!station){flash("No station matches that name.");return;}
  const r=buildStationClue(station.lat,station.lng);
  if(r.error){flash(r.error);return;}
  addClue(r.clue);
  highlightStation(station.lat,station.lng);
  document.getElementById("st-name").value="";
});
