/* ---- My location ---- */
const LocateControl=L.Control.extend({
  onAdd(){
    const b=L.DomUtil.create("button","leaflet-control-locate");
    b.type="button"; b.title="Show my location"; b.innerHTML="◎";
    L.DomEvent.on(b,"click",e=>{L.DomEvent.stop(e);map.locate({setView:true,maxZoom:14,enableHighAccuracy:true});});
    return b;
  }
});
map.addControl(new LocateControl({position:"topright"}));
let meDot=null, meRing=null;
map.on("locationfound",e=>{
  if(meDot){map.removeLayer(meDot);map.removeLayer(meRing);}
  meDot=L.circleMarker(e.latlng,{radius:6,color:"#fff",weight:2,fillColor:"#2875c7",fillOpacity:1}).addTo(map);
  meRing=L.circle(e.latlng,{radius:Math.max(e.accuracy,8),color:"#2875c7",weight:1,opacity:.5,fillOpacity:.08}).addTo(map);
  if(mePending){
    const key=mePending, m=PICKS[key];
    mePending=null;
    if(m){
      document.getElementById(m[0]).value=e.latlng.lat.toFixed(5);
      document.getElementById(m[1]).value=e.latlng.lng.toFixed(5);
      showDraft(key,e.latlng.lat,e.latlng.lng);
      if(e.accuracy>100){
        flash(`Location accuracy is about ${Math.round(e.accuracy)} m, worse than the recommended 100 m. Consider waiting for a better fix or picking manually.`);
      }
      document.body.classList.remove("nav-open");
      updateThermoDistance();
    }
  }
});
map.on("locationerror",()=>{
  mePending=null;
  setStatus("Location unavailable. It needs HTTPS (or localhost) and permission.",false); hideStatus(3500);
});

/* ========================= STATIONS ========================= */
const statusEl=document.getElementById("status");
function setStatus(html,spin){statusEl.innerHTML=(spin?`<span class="spin"></span>`:``)+html;statusEl.classList.add("show");}
function hideStatus(d){setTimeout(()=>statusEl.classList.remove("show"),d||2500);}
function stationsUpdated(){voronoiCache.clear();if(clues.length){drawDeduction();}else{render();}}
// Stations are the Google train-station set, baked in above. When served from the
// repo an updated data/stations.json (a fresh Google sweep) overrides the baked copy.
// Opened as a single file, the fetch fails harmlessly and the baked set is used.
async function loadStations(){
  try{
    const r=await fetch("data/stations.json",{cache:"no-cache"});
    if(r.ok){
      const d=await r.json();
      if(Array.isArray(d)&&d.length>300&&d.length!==STATIONS.length){
        STATIONS=d;stationsUpdated();
        setStatus(`${d.length.toLocaleString()} Google stations (updated dataset)`,false);hideStatus();
        return;
      }
    }
  }catch(e){}
  setStatus(`${STATIONS.length.toLocaleString()} Google stations`,false);hideStatus();
}

/* ========================= GOOGLE LIVE DATA ========================= */
const GTYPE={hospital:"hospital",museum:"museum",library:"library",cinema:"movie_theater",zoo:"zoo",aquarium:"aquarium",themepark:"amusement_park"};
function gstatus(msg){const el=document.getElementById("gstatus"); if(el) el.textContent=msg;}
function googleKey(){
  const box=document.getElementById("gkey");
  const typed=((box&&box.value)||"").trim();
  if(typed) return typed;
  return ((typeof window!=="undefined"&&window.GOOGLE_API_KEY)||"").trim();
}
try{const saved=localStorage.getItem("gmaps-key"); if(saved) document.getElementById("gkey").value=saved;}catch(e){}
document.getElementById("gkey").addEventListener("change",e=>{try{localStorage.setItem("gmaps-key",e.target.value.trim());}catch(err){}});
async function loadGoogleForView(){
  const key=googleKey();
  if(!key){gstatus("Paste an API key first. Without one the built-in sample stays active."); return;}
  const cats=CATS.filter(c=>state.enabled[c.id]);
  if(!cats.length){gstatus("Turn on at least one place category first."); return;}
  const c=map.getCenter(); const b=map.getBounds();
  const radius=Math.round(Math.min(50000,Math.max(1000,c.distanceTo(b.getNorthEast()))));
  gstatus("Loading from Google\u2026");
  let added=0;
  for(const cat of cats){
    try{
      const res=await fetch("https://places.googleapis.com/v1/places:searchNearby",{
        method:"POST",
        headers:{"Content-Type":"application/json","X-Goog-Api-Key":key,
          "X-Goog-FieldMask":"places.displayName,places.location,places.rating,places.userRatingCount"},
        body:JSON.stringify({includedTypes:[GTYPE[cat.id]],maxResultCount:20,
          locationRestriction:{circle:{center:{latitude:c.lat,longitude:c.lng},radius:radius}}})
      });
      if(!res.ok){const t=await res.text(); throw new Error("HTTP "+res.status+": "+t.slice(0,140));}
      const data=await res.json();
      for(const p of (data.places||[])){
        const name=p.displayName&&p.displayName.text; const loc=p.location;
        if(!name||!loc) continue;
        // Map boundary rule: places outside Switzerland do not exist for this game.
        if(!turf.booleanPointInPolygon(turf.point([loc.longitude,loc.latitude]),SWISS_FEATURE)) continue;
        if(TARGETS.some(x=>x[0]===name&&Math.abs(x[1]-loc.latitude)<1e-4&&Math.abs(x[2]-loc.longitude)<1e-4)) continue;
        TARGETS.push([name,loc.latitude,loc.longitude,cat.id,p.rating||0,p.userRatingCount||0]);
        added++;
      }
    }catch(err){gstatus("Google error for "+cat.label+": "+err.message); return;}
  }
  voronoiCache.clear(); render();
  gstatus(added?added+" Google places added for this view. They feed the deduction maths too.":"No new places returned for this view.");
}
document.getElementById("gload").addEventListener("click",loadGoogleForView);

// Complete per-category Google place data, when it has been swept and committed.
async function loadPlaces(){
  try{
    const r=await fetch("data/places.json",{cache:"no-cache"});
    if(!r.ok) return;
    const d=await r.json();
    let added=0;
    for(const cat of Object.keys(d)){
      for(const p of d[cat]){
        if(TARGETS.some(x=>x[0]===p[0]&&Math.abs(x[1]-p[1])<1e-4&&Math.abs(x[2]-p[2])<1e-4)) continue;
        TARGETS.push([p[0],p[1],p[2],cat,p[3]||0,p[4]||0]); added++;
      }
    }
    if(added){voronoiCache.clear();render();setStatus(`${added.toLocaleString()} Google places loaded`,false);hideStatus();}
  }catch(e){}
}

// Layers Google does not provide. Flagged in the interface as not Google-verified.
function osmStatus(msg){const el=document.getElementById("osm-note"); if(el) el.textContent=msg;}
async function loadOsm(){
  try{
    const r=await fetch("data/osm-layers.json",{cache:"no-cache"});
    if(!r.ok) throw new Error("missing");
    const d=await r.json();
    OSM.peaks=(d.peaks||[]).map(p=>({name:p[0],lat:p[1],lng:p[2],ele:p[3]}));
    OSM.waters=d.waters||[];
    OSM.minElevation=d.minElevation||0;
    OSM.loaded=true;
    waterLineCache=null; voronoiCache.clear();
    document.querySelectorAll("[data-osm]").forEach(o=>{o.disabled=false;});
    osmStatus(`Mountains (${OSM.peaks.length} peaks above ${OSM.minElevation} m) and ${OSM.waters.length} water bodies loaded from OpenStreetMap. Not Google-verified, so settle disputes on Google Maps.`);
  }catch(e){
    document.querySelectorAll("[data-osm]").forEach(o=>{o.disabled=true;});
    osmStatus("Mountain and water questions need data/osm-layers.json. Run scripts/fetch_osm_layers.py to enable them.");
  }
}
function districtStatus(msg){const el=document.getElementById("district-note"); if(el) el.textContent=msg;}
async function loadDistricts(){
  try{
    const r=await fetch("data/districts.json",{cache:"no-cache"});
    if(!r.ok) throw new Error("missing");
    const d=await r.json();
    DISTRICTS=(d.districts||[]).map(x=>({
      name:x.n,
      feature:x.r.length===1?turf.polygon(x.r):turf.multiPolygon(x.r.map(ring=>[ring]))
    }));
    districtLineCache=null; voronoiCache.clear();
    document.querySelectorAll("[data-district]").forEach(o=>{o.disabled=false;});
    districtStatus(`${DISTRICTS.length} districts loaded from OpenStreetMap. Not Google-verified, so settle disputes on Google Maps. Some cantons have none, which is a valid null answer.`);
  }catch(e){
    document.querySelectorAll("[data-district]").forEach(o=>{o.disabled=true;});
    districtStatus("District questions need data/districts.json. Run scripts/fetch_districts.py to enable them.");
  }
}
function transitStatus(msg){const el=document.getElementById("transit-note"); if(el) el.textContent=msg;}
async function loadTransitLines(){
  try{
    const r=await fetch("data/transit-lines.json",{cache:"no-cache"});
    if(!r.ok) throw new Error("missing");
    const d=await r.json();
    TRANSIT_LINES=d.lines||[];
    TRANSIT_BY_STATION=new Map();
    for(const line of TRANSIT_LINES){
      for(const name of line.stops){
        if(!TRANSIT_BY_STATION.has(name)) TRANSIT_BY_STATION.set(name,[]);
        TRANSIT_BY_STATION.get(name).push(line);
      }
    }
    document.querySelectorAll("[data-transit]").forEach(o=>{o.disabled=false;});
    transitStatus(`${TRANSIT_LINES.length} rail lines loaded from the Swiss GTFS feed. Heritage and rack railways are not covered, a known gap.`);
  }catch(e){
    document.querySelectorAll("[data-transit]").forEach(o=>{o.disabled=true;});
    transitStatus("Transit line questions need data/transit-lines.json. Run scripts/fetch_transit_lines.py to enable them.");
  }
}
function highspeedStatus(msg){const el=document.getElementById("highspeed-note"); if(el) el.textContent=msg;}
async function loadHighSpeedLines(){
  try{
    const r=await fetch("data/highspeed-lines.json",{cache:"no-cache"});
    if(!r.ok) throw new Error("missing");
    const d=await r.json();
    HIGHSPEED_LINES=d.lines||[];
    highspeedLineCache=null;
    document.querySelectorAll("[data-highspeed]").forEach(o=>{o.disabled=false;});
    highspeedStatus(`${HIGHSPEED_LINES.length} high-speed lines loaded (hand-maintained, EU definition). Not Google-verified.`);
  }catch(e){
    document.querySelectorAll("[data-highspeed]").forEach(o=>{o.disabled=true;});
    highspeedStatus("High-speed line questions need data/highspeed-lines.json.");
  }
}
function elevationStatus(msg){const el=document.getElementById("elevation-note"); if(el) el.textContent=msg;}
async function loadElevation(){
  try{
    const r=await fetch("data/elevation.json",{cache:"no-cache"});
    if(!r.ok) throw new Error("missing");
    const d=await r.json();
    ELEVATION_GRID=d;
    elevationFC=null; elevationFlat=null; elevationMax=null;
    document.querySelectorAll("[data-elevation]").forEach(o=>{o.disabled=false;});
    elevationStatus(`Elevation grid loaded (${d.spacingKm} km spacing, nearest ${d.roundedToM} m). Not Google-verified, (c) swisstopo.`);
  }catch(e){
    document.querySelectorAll("[data-elevation]").forEach(o=>{o.disabled=true;});
    elevationStatus("Elevation questions need data/elevation.json. Run scripts/fetch_elevation.py to enable them.");
  }
}


/* ========================= SHARE LINK ========================= */
// #v=2&z=<zone km>&r=<min reviews>&f=<stations>.<places>&c=<clue>~<clue>...
// Clue fields are | separated, coordinates to 5dp, distances always canonical
// kilometres. Geometry is rebuilt from these inputs on load, never shipped as
// GeoJSON, so it matches whatever clip()/circle()/voronoi logic the
// recipient's build actually runs. Each distance-bearing clue also carries
// the unit it was created in, purely so its label can still read the way the
// sender saw it -- imperial and metric are parallel rule sets, not
// conversions, so that label must never be silently re-derived.
const SHARE_VERSION=3;
function fmt5(n){return Number(n).toFixed(5);}
function parseNum(s){if(s===undefined||s===null||s==="")return null;const n=parseFloat(s);return Number.isFinite(n)?n:null;}
function encodeClueShare(s){
  if(!s) return null;
  switch(s.t){
    case "R": return ["R",fmt5(s.lat),fmt5(s.lng),s.km,s.hit?1:0,s.unit].join("|");
    case "T": return ["T",fmt5(s.aLat),fmt5(s.aLng),fmt5(s.bLat),fmt5(s.bLng),s.hotter?1:0,s.questionKm,s.unit].join("|");
    case "M": return ["M",s.mode,fmt5(s.lat),fmt5(s.lng),s.same?1:0].join("|");
    case "S": return ["S",s.ref,fmt5(s.lat),fmt5(s.lng),s.closer?1:0,s.unit].join("|");
    case "N": return ["N",s.ref,fmt5(s.lat),fmt5(s.lng),s.km,s.pLat!=null?fmt5(s.pLat):"",s.pLng!=null?fmt5(s.pLng):"",s.unit].join("|");
    case "P": return ["P",fmt5(s.lat),fmt5(s.lng)].join("|");
    default: return null;
  }
}
function buildShareUrl(){
  const p=new URLSearchParams();
  p.set("v",String(SHARE_VERSION));
  p.set("z",String(HIDE_RADIUS_KM));
  p.set("r",String(state.minReviews));
  p.set("f",`${STATIONS.length}.${TARGETS.length}`);
  p.set("c",clues.map(c=>encodeClueShare(c.share)).filter(Boolean).join("~"));
  return location.origin+location.pathname+"#"+p.toString();
}
async function decodeClueShare(fields){
  const t=fields[0];
  const lat=i=>parseNum(fields[i]), lng=i=>parseNum(fields[i]);
  switch(t){
    case "R": return buildRadarClue(lat(1),lng(2),parseNum(fields[3]),fields[5]||"mi",fields[4]==="1");
    case "T": return buildThermoClue(lat(1),lng(2),lat(3),lng(4),fields[5]==="1",parseNum(fields[6]),fields[7]||"mi");
    case "M": return buildMatchClue(fields[1],lat(2),lng(3),fields[4]==="1");
    case "S": return await buildMeasureClue(fields[1],lat(2),lng(3),fields[4]==="1",fields[5]||"mi");
    case "N": return buildTentacleClue(fields[1],lat(2),lng(3),parseNum(fields[4]),fields[7]||"mi",parseNum(fields[5]),parseNum(fields[6]));
    case "P": return buildStationClue(lat(1),lng(2));
    default: return {error:"Unrecognised clue type '"+t+"'."};
  }
}
function shareBanner(html,tone){
  const el=document.getElementById("share-banner");
  if(!el) return;
  el.className="show"+(tone?" "+tone:"");
  el.innerHTML=`<span class="share-banner-msg">${html}</span><button class="share-banner-x" aria-label="Dismiss">×</button>`;
  el.hidden=false;
  el.querySelector(".share-banner-x").addEventListener("click",()=>{el.hidden=true;});
}
async function replayShareLink(){
  const raw=location.hash.replace(/^#/,"");
  const params=new URLSearchParams(raw);
  const v=params.get("v");
  if(v!==String(SHARE_VERSION)){
    shareBanner(`This link uses share format v=${v||"?"}, which this build of the map does not understand. Loading the map normally instead.`,"warn");
    loadStations(); loadPlaces(); loadOsm(); loadDistricts(); loadTransitLines(); loadHighSpeedLines(); loadElevation();
    return;
  }
  const z=parseNum(params.get("z"));
  const r=parseNum(params.get("r"));
  const f=params.get("f")||"";
  const cRaw=params.get("c")||"";
  shareBanner("Loading shared map…","");
  await Promise.allSettled([loadStations(),loadPlaces(),loadOsm(),loadDistricts(),loadTransitLines(),loadHighSpeedLines(),loadElevation()]);
  if(z!==null&&UNIT_TABLE.zone.km.includes(z)){
    HIDE_RADIUS_KM=z;
    renderZoneOptions();
  }
  if(r!==null){
    state.minReviews=Math.max(0,Math.min(50,Math.round(r)));
    const rEl=document.getElementById("reviews"); if(rEl) rEl.value=state.minReviews;
    const rv=document.getElementById("rev-val"); if(rv) rv.textContent=state.minReviews;
  }
  const clueStrs=cRaw?cRaw.split("~").filter(Boolean):[];
  const replayed=[];
  let dropped=0;
  for(const cs of clueStrs){
    const fields=cs.split("|");
    try{
      const res=await decodeClueShare(fields);
      if(res&&res.clue) replayed.push(res.clue);
      else { dropped++; console.warn("Share link: dropped clue",cs,res&&res.error); }
    }catch(err){ dropped++; console.warn("Share link: dropped clue",cs,err); }
  }
  clues=replayed;
  renderClues();
  const fParts=f.split(".");
  const expStations=parseInt(fParts[0],10), expPlaces=parseInt(fParts[1],10);
  const mismatch=Number.isFinite(expStations)&&Number.isFinite(expPlaces)&&(expStations!==STATIONS.length||expPlaces!==TARGETS.length);
  let msg=`Shared map loaded: ${replayed.length} clue${replayed.length===1?"":"s"}`;
  if(dropped) msg+=`, <b style="color:#ffb020">${dropped} could not be replayed</b>`;
  msg+=`, ${fmtDist(HIDE_RADIUS_KM,UNITS)} zones, minimum ${state.minReviews} reviews.`;
  if(mismatch){
    msg+=`<br><b style="color:#ff6b6b">Dataset mismatch:</b> this link was made with ${Number.isFinite(expStations)?expStations:"?"} stations / ${Number.isFinite(expPlaces)?expPlaces:"?"} places; this map currently has ${STATIONS.length} / ${TARGETS.length}. Answers may differ from the sender's.`;
  }
  shareBanner(msg,mismatch?"mismatch":(dropped?"warn":""));
  showTab("narrow");
}
function shareMsg(text,ok){
  const el=document.getElementById("share-msg");
  if(!el) return;
  el.textContent=text; el.style.color=ok?"#22c55e":"#ff6b6b";
  clearTimeout(shareMsg._t);
  shareMsg._t=setTimeout(()=>{el.textContent="";},4000);
}
document.getElementById("share-map").addEventListener("click",async()=>{
  if(!clues.length){shareMsg("Add at least one clue first.",false);return;}
  const url=buildShareUrl();
  try{
    await navigator.clipboard.writeText(url);
    shareMsg("Link copied. Anyone who opens it sees this exact possible area.",true);
  }catch(err){
    shareMsg("Could not copy automatically. The link is in the browser console.",false);
    console.log("Share link:",url);
  }
});

refreshUnitUI();
render();
if(location.hash){ replayShareLink(); } else {
  try{
    const saved=JSON.parse(localStorage.getItem("clues"));
    if(Array.isArray(saved)&&saved.length) clues=saved;
  }catch(e){}
  loadStations(); loadPlaces(); loadOsm(); loadDistricts(); loadTransitLines(); loadHighSpeedLines(); loadElevation();
  renderClues();
}
